(()=>{
  const C=Cimora,{S,M,E,ui,btn,link,art,badge,money,path,meta}=C;
  const catalog=[
    {id:'story-skill',title:'让对白，有潜台词',type:'技能',category:'故事创作',desc:'保留人物目标，润色对白与场景动作。',price:80,art:2,author:'青空叙事',uses:'文本输入 → 故事候选',steps:['读取人物与场景约束','分析对白意图','输出可比较的修改候选']},
    {id:'rain-layout',title:'雨日来信 · 呼吸感条漫',type:'模板',category:'漫画排版',desc:'宽松留白、克制对白，让每次重逢都有余韵。',price:120,art:6,author:'雾岛设计室',uses:'分格素材 → 竖向条漫',steps:['引用章节分格','应用宽松排版','检查气泡与阅读顺序']},
    {id:'film-workflow',title:'从一章故事，到动态预告',type:'工作流',category:'视频',desc:'分镜、资产、关键镜头和审查的完整配方。',price:180,art:10,author:'Cimora Studio',uses:'章节内容 → 镜头工程',steps:['提取人物场景道具','规划镜头与稳定运镜','选择关键镜头增强','审查并生成交付快照']},
    {id:'oc-identity',title:'OC 身份档案 · 连续创作版',type:'模板',category:'角色资产',desc:'让外观、服装、情绪与故事关系有据可依。',price:60,art:1,author:'月见绘研',uses:'角色描述 → 参考档案',steps:['整理身份约束','保存服装和表情参考','建立项目版本引用']},
    {id:'continuity-skill',title:'道具与服装连续性检查',type:'技能',category:'工程效率',desc:'从章节变化中找到需要创作者确认的地方。',price:90,art:3,author:'白昼工程室',uses:'章节与资产 → 差异清单',steps:['读取固定资产版本','比较章节状态','定位需要确认的分格']},
    {id:'starter-free',title:'第一章 · 新人创作配方',type:'工作流',category:'入门',desc:'从一句想法开始，用最少步骤完成第一章。',price:0,art:8,author:'Cimora Studio',uses:'灵感描述 → 第一章草稿',steps:['扩写故事方向','拆章与分镜','确认草图','完成漫画排版']}
  ];
  const works=[{id:'rain-public',title:'雨停之前',author:'Cimora Originals',type:'both',tag:'都市情感',art:6,desc:'一封没寄出的信，和一场迟到七年的重逢。'},{id:'sky-public',title:'星海邮局',author:'月见绘研',type:'comic',tag:'幻想治愈',art:10,desc:'她替星星寄信，也在寻找自己的归处。'},{id:'book-public',title:'慢日子书店',author:'Cimora Originals',type:'comic',tag:'日常切片',art:0,desc:'在旧书与雨声之间，捡起被遗忘的温柔。'},{id:'light-public',title:'微光来信',author:'雾岛设计室',type:'motion',tag:'情绪短片',art:8,desc:'黄昏落进眼睛，故事才刚刚开始。'}];
  function heading(k,h,p='',a=''){return `<div class="cm-page-heading"><div><span class="cm-kicker">${k}</span><h1>${h}</h1><p>${p}</p></div><div>${a}</div></div>`;}
  function projectCard(p){const c=M.resume(p),e=c.e;return `<article class="cm-project-card"><a href="#/app/projects/${p.id}">${art(p.art,p.name)}<span class="cm-image-badge">${M.output(p)==='comic'?'漫画':M.output(p)==='motion'?'视频':'漫画 + 视频'}</span><div class="cm-project-hover">继续故事 ↗</div></a><div><small>${p.chapters.length} 章 · ${p.assetIds?.length||0} 项资产</small><h3>${link(E(p.name),'/app/projects/'+p.id,'')}</h3><p>${E(p.desc)}</p><footer><span><i></i>${E(p.updated||'本机草稿')}</span>${link('继续：'+E(M.navigation?.task(c)||e.stage),M.navigation?.resume(c)||path(c,e.stage),'cm-text-link')}</footer></div></article>`;}
  function home(){const ps=S.state.projects.filter(p=>!p.archived);return heading('YOUR CREATIVE UNIVERSE','欢迎回来，创作者。','每一个世界，都从你的想象开始。',link('＋ 新建项目','/app/new','cm-button primary'))+`<section class="cm-dashboard-hero"><img src="assets/cimora-cover.webp" alt="Cimora 原创星海少女与幻想城市" class="cm-hero-image"><div class="cm-dashboard-hero-copy"><span class="cm-kicker">WHERE YOUR STORIES COME ALIVE</span><h2>把脑海里的世界，<br>变成下一部作品。</h2><p>一句灵感、一章漫画、一段会动的故事。<br>让角色与故事，在同一个宇宙里生长。</p><div>${link('✧ 从灵感开始','/app/new?source=idea','cm-button primary')}${link('⌘ 自由画布','/app/new?view=canvas','cm-button glass')}</div></div><span class="cm-original-mark">CIMORA ORIGINAL WORLD / 001</span></section><div class="cm-quick-starts">${[['✎','漫画创作','分镜、草图到长图排版','comic'],['▷','视频创作','镜头、声音到动态演绎','motion'],['⌘','无限画布','让灵感与流程自由连接','canvas'],['✧','创作小工具','为正在做的作品添一点灵感','tools']].map(([ic,t,d,v])=>link(`<span>${ic}</span><div><h3>${t}</h3><p>${d}</p></div><b>↗</b>`,v==='tools'?'/app/tools':v==='canvas'?'/app/new?view=canvas':'/app/new?output='+v,'cm-quick-start')).join('')}</div><div class="cm-section-head"><div><span class="cm-kicker">CONTINUE CREATING</span><h2>故事，还在继续。</h2></div>${link('全部项目 →','/app/projects','cm-text-link')}</div><div class="cm-project-grid">${ps.slice(0,3).map(projectCard).join('')}${ps.length<3?link('<b>＋</b><h3>下一个世界</h3><p>从一个小小的想法开始。</p>','/app/new','cm-empty-project'):''}</div><div class="cm-section-head"><div><span class="cm-kicker">MADE WITH IMAGINATION</span><h2>来自创作宇宙的灵感。</h2></div>${link('探索作品广场 →','/app/community','cm-text-link')}</div><div class="cm-discovery-row">${works.slice(1).map(workCard).join('')}</div>`;}
  function projects(ctx){if(ctx.parts[2])return C.project(S.project(ctx.parts[2]));return heading('YOUR ORIGINAL WORLDS','我的项目','项目是故事的家，章节是每一次继续。',link('＋ 新建项目','/app/new','cm-button primary'))+`<div class="cm-filter-toolbar"><label class="cm-search">⌕<input placeholder="搜索项目…" aria-label="搜索 Cimora 项目" data-cm-input="project-search" value="${E(ui.projectSearch||'')}"></label>${btn('查看归档','show-archive','cm-button ghost')}</div><div class="cm-project-grid" id="cm-project-list">${projectList()}</div>`;}
  function projectList(){return S.state.projects.filter(p=>!p.archived&&(!ui.projectSearch||(p.name+p.desc).includes(ui.projectSearch))).map(projectCard).join('')||'<div class="cm-empty-small">没有匹配项目。试试另一个关键词。</div>';}
  function newProject(ctx){const d=M.db.newDraft??={name:'',text:'',source:ctx.params.get('source')||'idea',output:ctx.params.get('output')||'comic',view:ctx.params.get('view')||'flow',tone:'细腻治愈',candidate:'',direction:0};if(ctx.params.get('view'))d.view=ctx.params.get('view');if(ctx.params.get('output'))d.output=ctx.params.get('output');if(ctx.params.get('source'))d.source=ctx.params.get('source');return heading('LET’S MAKE SOMETHING YOURS','你的下一个故事，从哪里开始？','不需要准备好完整故事。先写一句想法，我们一起把它展开。')+`<div class="cm-new-layout"><section class="cm-panel cm-new-input"><div class="cm-source-tabs">${[['idea','✧','一句灵感'],['novel','▤','小说改编'],['script','文','已有故事'],['comic','▦','导入漫画']].map(([k,ic,t])=>btn(`${ic} ${t}`,'new-source',d.source===k?'selected':'',`data-source="${k}"`)).join('')}</div><label class="cm-label">给故事起个名字 <small>也可以稍后再想</small><input id="cm-new-name" placeholder="例如：雨停之前" data-cm-input="new-name" value="${E(d.name)}" maxlength="60"></label><label class="cm-label">${d.source==='idea'?'描述你脑海里的画面':d.source==='novel'?'粘贴想改编的小说片段':d.source==='script'?'粘贴已有故事故事':'描述漫画内容（可选）'}<textarea id="cm-new-text" data-cm-input="new-text" rows="7" placeholder="一个女孩回到阔别多年的旧书店，重逢一直在等她的人。她带着一封没有寄出的信……">${E(d.text)}</textarea></label>${d.source==='comic'?'<label class="cm-upload">↥ 选择漫画图片<input type="file" id="cm-new-file" accept="image/*" multiple><small>本机预览；切格与识别为示例</small></label>':''}<div class="cm-inline-actions">${btn('试试这个灵感','sample-idea','cm-text-link')}<span>原始输入始终保留</span></div><div class="cm-new-options"><label class="cm-label">故事基调<select id="cm-new-tone" data-cm-change="new-tone">${['细腻治愈','悬疑反转','奇幻冒险','轻松日常'].map(t=>`<option ${d.tone===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="cm-label">目标作品<select id="cm-new-output" data-cm-change="new-output"><option value="comic" ${d.output==='comic'?'selected':''}>漫画</option><option value="motion" ${d.output==='motion'?'selected':''}>视频</option><option value="both" ${d.output==='both'?'selected':''}>漫画 + 视频</option></select></label></div><div class="cm-inline-actions">${btn('✧ 帮我扩写故事','new-expand','cm-button primary')}${btn('✎ 只润色原文','new-polish','cm-button ghost')}</div><small class="cm-help">本机示例组织剧情结构，不调用文本模型。你的描述与修改会保存。</small></section><section class="cm-panel cm-new-output"><div class="cm-panel-title"><div><span class="cm-kicker">STORY CO-CREATION</span><h2>给灵感，一点生长的空间。</h2></div><span class="cm-sparkle">✦</span></div><div class="cm-direction-tabs">${['细腻重逢','悬疑来信','奇幻约定'].map((t,i)=>btn(t,'story-direction',d.direction===i?'selected':'',`data-index="${i}"`)).join('')}</div>${d.candidate?`<label class="cm-label">故事候选 / 可编辑<textarea id="cm-new-candidate" data-cm-input="new-candidate" rows="14">${E(d.candidate)}</textarea></label>`:`<div class="cm-story-placeholder">${art(3,'未寄出的信')}<h3>一封信，也可以是一整个故事。</h3><p>写下你的灵感，生成故事方向、大纲与对白候选。<br>不满意的部分，可以继续修改。</p></div>`}<div class="cm-start-choice"><strong>选择你的创作方式</strong><div>${btn('☷ 流程引导 <small>一步步确认内容</small>','new-view',d.view==='flow'?'selected':'','data-view="flow"')}${btn('⌘ 无限画布 <small>从关联和灵感开始</small>','new-view',d.view==='canvas'?'selected':'','data-view="canvas"')}</div></div><div class="cm-new-submit">${btn('创建项目，继续这个故事 ↗','create-cimora-project','cm-button primary full')}${btn('从空白无限画布开始','create-blank-project','cm-text-link')}</div></section></div>`;}
  function scopedAssets(){const c=C.ctx();return S.state.assets.filter(a=>{const match=ui.assetScope==='studio'?!a.projectId:ui.assetScope==='project'?a.projectId===c.p.id||c.p.assetIds?.includes(a.id):!!c.e.bindings[a.id]||a.projectId===c.p.id&&a.chapterIds?.includes(c.c.id);return match&&(ui.assetType==='全部'||a.type===ui.assetType)&&(!ui.assetSearch||(a.name+a.desc).includes(ui.assetSearch));});}
  function assetCard(a){return `<button class="cm-library-asset" data-cm="asset-detail" data-id="${a.id}"><div>${art(a.art,a.name)}<span class="cm-image-badge">${E(a.type)}</span></div><section><h3>${E(a.name)}</h3><p>${a.projectId?E(S.project(a.projectId)?.name||'项目'):'工作室通用'}${a.chapterIds?.length?' / '+a.chapterIds.length+' 章':''}</p><footer><span>${a.locked?'● 已锁定':'◌ 草稿'} · v${a.version}</span><b>↗</b></footer></section></button>`;}
  function assets(ctx){if(ctx.parts[2]){const a=S.state.assets.find(a=>a.id===ctx.parts[2]);return a?assetDetail(a):S.empty('资产不存在','返回资产库。','资产库','/app/assets');}return heading('YOUR WORLD, ORGANIZED','每份素材，都有自己的位置。','按项目和章节找到需要的内容，跨章节引用同一份固定版本。',btn('＋ 创建资产','new-asset','cm-button primary'))+C.scopePicker()+`<div class="cm-library-scope">${[['chapter','本章使用'],['project','项目全部'],['studio','工作室通用']].map(([k,t])=>btn(t,'asset-scope',ui.assetScope===k?'selected':'',`data-scope="${k}"`)).join('')}</div><div class="cm-filter-toolbar"><div class="cm-filter-tabs">${['全部','角色','场景','道具','服装','画风','声音','背景音乐','环境声','动作音效'].map(t=>btn(t,'library-type',ui.assetType===t?'selected':'',`data-type="${t}"`)).join('')}</div><label class="cm-search">⌕<input placeholder="搜索资产、约束…" aria-label="搜索 Cimora 资产" data-cm-input="asset-search" value="${E(ui.assetSearch)}"></label></div><div class="cm-library-grid" id="cm-library-grid">${assetList()}</div><div class="cm-notice">本章引用不会复制素材。新版本需要主动同步；草图与候选在章节分镜和版本记录中管理。</div>`;}
  const assetList=()=>scopedAssets().map(assetCard).join('')||'<div class="cm-empty-small">此范围还没有资产。可以创建、从项目引用，或使用创作工具生成示例。</div>';
  function assetDetail(a){const refs=S.state.projects.flatMap(p=>[...p.chapters,...(p.episodes||[])].map(ch=>({p,ch,e:M.ensure(p,ch)}))).filter(c=>c.e.bindings[a.id]);return heading('ASSET & REFERENCES',E(a.name),`${a.type} / ${a.projectId?E(S.project(a.projectId)?.name||'项目'):'工作室通用'} / v${a.version}`,btn('创建新版本','asset-revise','cm-button primary',`data-id="${a.id}"`))+`<div class="cm-asset-detail"><div>${art(a.art,a.name)}</div><section class="cm-panel"><h3>身份与视觉约束</h3><p>${E(a.desc)}</p><div class="cm-detail-lines"><span>当前版本<b>v${a.version}</b></span><span>状态<b>${a.locked?'已锁定':'草稿'}</b></span><span>引用位置<b>${refs.length} 个章节</b></span></div>${!a.locked?btn('锁定当前版本','cm-lock-asset','cm-button ghost',`data-id="${a.id}"`):''}${btn('查看版本变更影响','asset-impact','cm-button ghost',`data-id="${a.id}"`)}${btn('引用到当前章节','bind-asset','cm-button primary',`data-id="${a.id}"`)}<h3>固定版本引用</h3>${refs.map(c=>`<div class="cm-asset-reference"><div><strong>${E(c.p.name)} / ${E(c.ch.title)}</strong><small>引用 v${c.e.bindings[a.id]} ${c.e.bindings[a.id]!==a.version?'· 新版本可同步':'· 与当前一致'}</small></div>${link('查看章节',path({p:c.p,c:c.ch,e:c.e},'assets'),'cm-text-link')}</div>`).join('')||'<p>还没有章节引用。</p>'}<h3>历史约束</h3>${(a.history||[]).slice().reverse().map(h=>`<p><b>v${h.version}</b> ${E(h.desc)}</p>`).join('')||'<p>初始版本，无历史变更。</p>'}</section></div>`;}
  function marketCard(it){const installed=M.db.purchases.includes(it.id);return link(`<div class="cm-market-picture">${art(it.art,it.title)}<span class="cm-image-badge">${it.type}</span><b>↗</b></div><div class="cm-market-copy"><small>${it.category} / BY ${E(it.author)}</small><h3>${E(it.title)}</h3><p>${E(it.desc)}</p><footer><span>${installed?'✓ 已加入资源库':it.price?'✦ '+it.price+' 积分':'免费'}</span><span>${it.type==='技能'?'SKILL':it.type==='工作流'?'WORKFLOW':'TEMPLATE'}</span></footer></div>`,'/app/market/'+it.id,'cm-market-card');}
  function allCatalog(){return [...catalog,...M.db.drafts.filter(d=>d.published)];}
  function market(ctx){const item=ctx.parts[2]&&allCatalog().find(it=>it.id===ctx.parts[2]);if(ctx.parts[2])return item?marketDetail(item):S.empty('资源不存在','返回创作市场。','创作市场','/app/market');return heading('MADE BY CREATORS, FOR CREATORS','让好方法，被更多人看见。','探索技能、创作模板和工作流，把别人的经验变成你的新起点。',link('成为创作者 ↗','/app/creator','cm-button ghost'))+`<section class="cm-market-banner"><div><span class="cm-kicker">THE CREATOR EXCHANGE</span><h2>灵感值得分享，<br>经验也有自己的价值。</h2><p>用积分交换创作方法。购买资源与模型运行费用分别显示。</p></div>${art(10,'原创星海世界')}</section><div class="cm-filter-toolbar"><div class="cm-filter-tabs">${['全部','技能','模板','工作流','已拥有'].map(t=>btn(t,'market-filter',ui.marketType===t?'selected':'',`data-type="${t}"`)).join('')}</div>${link('✦ '+M.db.wallet+' 积分','/app/wallet','cm-credit-pill')}</div><div class="cm-market-grid">${allCatalog().filter(it=>ui.marketType==='全部'||ui.marketType==='已拥有'?ui.marketType==='全部'||M.db.purchases.includes(it.id):it.type===ui.marketType).map(marketCard).join('')||'<div class="cm-empty-small">资源库还是空的，先领取免费的新人创作配方。</div>'}</div>`;}
  function marketDetail(it){const owns=M.db.purchases.includes(it.id);return `<div class="cm-market-detail-header">${link('← 创作市场','/app/market','cm-back')}<div><span class="cm-soft-tag">${it.type} / ${it.category}</span><h1>${E(it.title)}</h1><p>${E(it.desc)}</p><small>BY ${E(it.author)} · 资源 v1.0 · 本机商品示例</small></div></div><div class="cm-market-detail"><div><div class="cm-market-main-art">${art(it.art,it.title)}</div><section class="cm-panel"><h3>你会得到什么</h3><p>${E(it.uses)}</p><ol class="cm-template-steps">${it.steps.map(t=>`<li>${E(t)}</li>`).join('')}</ol><h3>输入、权限与费用</h3><p>读取你主动选择的章节内容与参考资产，输出候选供你确认。此版本不执行外部代码，不获取密钥。</p><p>许可示例：可用于自己的创作项目；不可原样转售。正式许可需由创作者明确确认。</p></section></div><aside class="cm-panel"><span class="cm-kicker">ADD TO YOUR PROCESS</span><h2>${owns?'已在资源库':it.price?'✦ '+it.price+' 积分':'免费领取'}</h2><p>资源购买一次，模型调用按运行量另计。原型仅模拟积分，不产生真实交易。</p>${btn(owns?'在当前项目中使用':'加入我的资源库',owns?'use-market':'buy-market','cm-button primary full',`data-id="${it.id}"`)}${C.scopePicker()}<div class="cm-notice">使用时会展示将新增或应用的内容，不会覆盖已有作品。</div>${link('查看积分账本 →','/app/wallet','cm-text-link')}</aside></div>`;}
  function workCard(w){return link(`<div class="cm-work-picture">${art(w.art,w.title)}<span>${w.type==='comic'?'漫画':w.type==='motion'?'▷ 视频':'漫画 / 视频'}</span>${w.local?'<b>本机发布</b>':''}</div><div><h3>${E(w.title)} <span>↗</span></h3><p>${E(w.author)} <small>· ${w.tag||'原创作品'}</small></p></div>`,'/app/community/'+w.id,'cm-work-card');}
  function community(ctx){const list=[...M.db.publications,...works],w=ctx.parts[2]&&list.find(w=>w.id===ctx.parts[2]);if(ctx.parts[2])return w?workDetail(w):S.empty('作品不存在','返回作品广场。','作品广场','/app/community');return heading('A UNIVERSE OF ORIGINAL STORIES','每一种想象，都值得被看见。','遇见新的角色、世界和创作者。官网案例与公开作品，在这里各有位置。',btn('发布我的作品','publish-work','cm-button primary'))+`<div class="cm-gallery-feature">${art(10,'星海邮局原创幻想世界')}<div><span class="cm-kicker">CIMORA ORIGINALS / FEATURED</span><h2>星海邮局</h2><p>把未说出口的话，寄往星星住的地方。</p>${link('走进这个世界 ↗','/app/community/sky-public','cm-button glass')}</div></div><div class="cm-filter-toolbar"><div class="cm-filter-tabs">${['全部','漫画','视频','我的收藏','我的发布'].map(t=>btn(t,'gallery-filter',ui.galleryType===t?'selected':'',`data-type="${t}"`)).join('')}</div><small class="cm-help">精选为原创演示作品 · 无虚构人气数据</small></div><div class="cm-gallery-grid">${list.filter(w=>ui.galleryType==='全部'||ui.galleryType==='漫画'&&w.type!=='motion'||ui.galleryType==='视频'&&w.type!=='comic'||ui.galleryType==='我的收藏'&&M.db.favorites.includes(w.id)||ui.galleryType==='我的发布'&&w.local).map(workCard).join('')||'<div class="cm-empty-small">这里还没有作品。收藏喜欢的世界，或发布自己的本机快照。</div>'}</div>`;}
  function workDetail(w){const favor=M.db.favorites.includes(w.id),boards=w.snapshot?.boards||M.context('rain','ch1').e.boards;return `<div class="cm-work-detail"><section><div class="cm-work-feature">${art(w.art,w.title)}<span>${w.local?'本机发布快照':'CIMORA ORIGINAL DEMO'}</span></div><div class="cm-panel"><div class="cm-panel-title"><h1>${E(w.title)}</h1>${btn(favor?'♥ 已收藏':'♡ 收藏','favorite-work','cm-button ghost',`data-id="${w.id}"`)}</div><p>${E(w.author)} · ${E(w.desc||w.snapshot?.chapter||'我的原创作品')}</p><div class="cm-inline-actions">${btn('漫画阅读','work-view','cm-button primary small','data-view="comic"')}${btn('动态示意','work-view','cm-button ghost small','data-view="motion"')}</div><div id="cm-work-reader" class="cm-work-reader">${boards.map(b=>`<figure>${art(b.art,b.title)}<figcaption>${E(b.dialogue)}</figcaption></figure>`).join('')}</div></div></section><aside class="cm-panel"><span class="cm-kicker">BEHIND THE STORY</span><h3>故事背后的创作方法。</h3><p>作品展示与源工程授权分别管理。这里不会自动公开作者的提示词、资产和项目文件。</p>${!w.local?link('探索关联创作模板 →','/app/market/rain-layout','cm-button primary full'):'<div class="cm-notice">这是独立发布快照。继续修改工程，不会改变本页内容。</div>'}${link('回到作品广场','/app/community','cm-button ghost full')}<small class="cm-help">动态为运镜示意，未生成真实视频。示例作品之间共用部分原创演示画面。</small></aside></div>`;}
  function wallet(){return heading('YOUR CREATIVE RESOURCES','积分与资源','购买、领取与创作者收益分别记录。积分仅为本机演示。',link('发现新资源 ↗','/app/market','cm-button primary'))+`<div class="cm-wallet-overview"><section><span>可用积分</span><h2>✦ ${M.db.wallet}</h2><p>本机示例余额 · 不提现 · 无真实支付</p></section><section><span>我的资源库</span><h2>${M.db.purchases.length}<small> 项</small></h2><p>技能、模板和工作流</p></section></div><div class="cm-market-grid">${allCatalog().filter(it=>M.db.purchases.includes(it.id)).map(marketCard).join('')}</div><section class="cm-panel"><h3>积分账本</h3>${M.db.ledger.map(l=>`<div class="cm-ledger-row"><span>${E(l.title)}</span><small>${new Date(l.time).toLocaleDateString('zh-CN')}</small><b>${l.delta>0?'+':''}${l.delta}</b></div>`).join('')||'<p>还没有积分变动。首次示例余额为 680 积分。</p>'}<p class="cm-help">模型运行预算使用美元示例单独展示，不从此余额扣除。</p></section>`;}
  function creator(){return heading('SHARE WHAT YOU KNOW','把好用的方法，变成下一份灵感。','发布你的技能和创作模板。收益来自有效交易，上传草稿不会直接奖励积分。',btn('＋ 创建资源草稿','creator-draft','cm-button primary'))+`<div class="cm-creator-intro"><span>✦</span><div><h2>创作者，也可以创造工具。</h2><p>给资源清楚的输入、输出、示例与授权，帮助别人完成创作。</p></div></div><section class="cm-panel"><h3>我的资源</h3>${M.db.drafts.map(d=>`<div class="cm-candidate-row"><div><strong>${E(d.title)}</strong><p>${d.type} · ${d.price} 积分 · ${d.published?'本机上架示例':'草稿待完善'}</p></div>${btn(d.published?'查看商品':'预览并模拟上架',d.published?'open-market':'publish-resource','cm-button ghost',`data-id="${d.id}"`)}</div>`).join('')||'<p>还没有资源草稿。先分享一个你反复使用的创作方法。</p>'}</section>`;}
  function tasks(){const c=C.ctx();return C.runs(c);}
  function publicHome(){return `<main class="cm-public-home"><header class="cm-public-hero"><img src="assets/cimora-cover.webp" alt="Cimora 原创二次元幻想世界"><div class="cm-public-hero-copy"><span class="cm-kicker">FOR EVERY WORLD INSIDE YOU</span><h1>你的想象，<br>值得一个<span>宇宙。</span></h1><p>从一句灵感，到一章漫画，再到会动的故事。<br>在 Cimora，把你热爱的世界，亲手创造出来。</p><div>${link('进入创作空间 ↗','/app','cm-button primary large')}${link('探索作品','/app/community','cm-button glass large')}</div><small>故事共创 / 统一资产 / 自由画布 / 动态演绎</small></div><div class="cm-public-art-caption">ORIGINAL WORLD NO.001<br><strong>星海邮局 / LETTERS TO THE STARS</strong></div></header><section class="cm-public-manifesto"><span>YOUR STORY.</span><i>✦</i><span>YOUR CHARACTERS.</span><i>✦</i><span>YOUR UNIVERSE.</span></section><section class="cm-public-section"><span class="cm-kicker">FROM YOUR FIRST SPARK</span><h2>灵感不必完整，<br>故事可以一起长大。</h2><div class="cm-public-entry-grid">${[['✧','只有一句灵感','从故事方向、大纲到章节内容。','idea'],['▤','想让小说被看见','提炼人物、动作与可视化分镜。','novel'],['▦','已经拥有漫画','让分格、角色和对白继续成为动态故事。','comic']].map(([ic,h,p,v])=>link(`<span>${ic}</span><h3>${h}</h3><p>${p}</p><b>开始创作 ↗</b>`,'/app/new?source='+v,'')).join('')}</div></section><section class="cm-public-split"><div>${art(6,'雨停之前原创二次元作品')}</div><article><span class="cm-kicker">ONE WORLD, MANY WAYS TO CREATE</span><h2>同一个故事，<br>不止一种表达。</h2><p>漫画用留白安排情绪，视频用镜头和声音延续故事。角色、场景、道具与每一次修改，在同一个工程里保持联系。</p><div>${link('☷ 跟着流程开始','/app/new','cm-button primary')}${link('⌘ 打开自由画布','/app/new?view=canvas','cm-button ghost')}</div></article></section><section class="cm-public-section"><div class="cm-section-head"><div><span class="cm-kicker">CREATED, NOT JUST GENERATED</span><h2>让每一份创作，都有迹可循。</h2></div>${link('体验制作编排 →','/app/tasks','cm-text-link')}</div><div class="cm-public-benefits">${[['◈','角色始终属于你的世界','项目与章节固定引用资产版本，修改后只同步受影响的画面。'],['⌘','按自己的习惯创作','在流程和无限画布之间切换，内容、依赖和候选始终相连。'],['↶','好作品，留有余地','成功结果保留，失败步骤单独重试，增强不覆盖稳定底稿。']].map(([ic,h,p])=>`<article><span>${ic}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="cm-public-section"><div class="cm-section-head"><div><span class="cm-kicker">A UNIVERSE OF CREATORS</span><h2>遇见新世界，也分享你的世界。</h2></div>${link('走进作品广场 →','/app/community','cm-text-link')}</div><div class="cm-discovery-row">${works.slice(0,3).map(workCard).join('')}</div></section><section class="cm-public-cta"><span>✦</span><h2>下一部你喜欢的作品，<br>也许就出自你手。</h2>${link('开始创造你的宇宙 ↗','/app','cm-button primary large')}<p>Cimora · 二次元故事创作空间</p></section></main>`;}
  C.pages={home,projects,new:newProject,assets,tasks,market,community,wallet,creator};C.publicHome=publicHome;C.catalog=allCatalog;C.projectList=projectList;C.assetList=assetList;C.scopedAssets=scopedAssets;C.works=()=>[...M.db.publications,...works];
})();
